import { createTestDatabase } from './test-database.mjs';
import { writeFile } from 'node:fs/promises';
const db = await createTestDatabase();
const tables = (
  await db.query(
    `select table_name from information_schema.tables where table_schema='public' order by table_name`,
  )
).rows;
const tsType = (t) =>
  ({
    uuid: 'string',
    text: 'string',
    date: 'string',
    timestamptz: 'string',
    bool: 'boolean',
    int2: 'number',
    int4: 'number',
    int8: 'number',
    jsonb: 'Json',
    _text: 'string[]',
  })[t] || 'Json';
let out =
  '// Generated by npm run db:types from the versioned SQL migrations. Do not hand-edit.\nexport type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];\nexport interface Database { public: { Tables: {\n';
for (const { table_name: table } of tables) {
  const cols = (
    await db.query(
      `select column_name,udt_name,is_nullable,column_default from information_schema.columns where table_schema='public' and table_name=$1 order by ordinal_position`,
      [table],
    )
  ).rows;
  const row = cols
    .map(
      (c) =>
        `        ${c.column_name}: ${tsType(c.udt_name)}${c.is_nullable === 'YES' ? ' | null' : ''};`,
    )
    .join('\n');
  const insert = cols
    .map(
      (c) =>
        `        ${c.column_name}${c.is_nullable === 'YES' || c.column_default ? '?' : ''}: ${tsType(c.udt_name)}${c.is_nullable === 'YES' ? ' | null' : ''};`,
    )
    .join('\n');
  const relationships = (
    await db.query(
      `select conname, a.attname as col, ref.relname as ref_table, ra.attname as ref_col from pg_constraint c join pg_class r on r.oid=c.conrelid join pg_namespace ns on ns.oid=r.relnamespace join pg_class ref on ref.oid=c.confrelid join pg_attribute a on a.attrelid=r.oid and a.attnum=c.conkey[1] join pg_attribute ra on ra.attrelid=ref.oid and ra.attnum=c.confkey[1] where c.contype='f' and ns.nspname='public' and r.relname=$1`,
      [table],
    )
  ).rows;
  out += `    ${table}: {\n      Row: {\n${row}\n      };\n      Insert: {\n${insert}\n      };\n      Update: Partial<Database['public']['Tables']['${table}']['Insert']>;\n      Relationships: [${relationships.map((r) => `{ foreignKeyName: '${r.conname}'; columns: ['${r.col}']; isOneToOne: false; referencedRelation: '${r.ref_table}'; referencedColumns: ['${r.ref_col}'] }`).join(',')}];\n    };\n`;
}
out += `  }; Views: Record<never, never>; Functions: { [key: string]: { Args: Record<string, unknown>; Returns: Json } }; Enums: Record<never, never>; CompositeTypes: Record<never, never>; } }\nexport type Row<T extends keyof Database['public']['Tables']> = Database['public']['Tables'][T]['Row'];\n`;
await writeFile('src/types/database.ts', out);
await db.close();
console.log('Generated schema types.');
